import { HlmTypographyImports } from '@spartan-ng/helm/typography';
import type { Hero, HeroStatus } from '../../hero/hero.model';
import { PowerMeter } from '../power-meter/power-meter';

type StatusVariant = 'success' | 'warning' | 'secondary' | 'destructive';

const STATUS_VARIANT: Record<HeroStatus, StatusVariant> = {
  Active: 'success',
  Injured: 'warning',
  Reserve: 'secondary',
  MIA: 'destructive',
};

// Presentational: the hero arrives as an input; the card injects no data service.
@Component({
  selector: 'app-hero-card',
  imports: [
    RouterLink,
    HlmAvatarImports,
    HlmBadgeImports,
    HlmButtonImports,
    HlmCardImports,
    HlmTypographyImports,
    PowerMeter,
  ],
  templateUrl: './hero-card.html',
  styleUrl: './hero-card.css',
})
export class HeroCard {
  readonly hero = input.required<Hero>();

  protected readonly initials = computed(() =>
    this.hero()
      .name.split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part[0].toUpperCase())
      .join(''),
  );

  protected readonly statusVariant = computed(() => STATUS_VARIANT[this.hero().status]);
}
